cards=[]
c=compact('chang_lao','长老（山腹外星人）','长老被奉为降头术一派的源头，长期困在山腹，只能与走进特定范围的人交流。蓝丝对他既尊敬又关心，想筹集巨款使他脱困；温宝裕和白素进入之后，却发现自己的问题还没有形成就会被他的脑能量抹去。卫斯理等人把电脑和洞外提问者接入交流，才逐步打破信息不对等。长老最终交代，他是七种联合寻找生命延续之地的外星人之一，负责地球改造工程的一处爆炸，故障使他受困，也使原有计划出现差错。修复之后，他仍握有足以造成全球灾难的爆炸力量，却始终不用，因为那会消灭已经产生的生命，违背他们迁来的目的。获得大量现代资料后，他认定地球将重复母星人口过度增长的毁灭，提出大幅减少人口，并准备改变人们对生命的依恋来实行。其保护星体的真诚与对个体意愿的忽视同时存在。终局他仍未开关，温宝裕继续提供网络信息；他的知识和行动目标有继续变化的空间，不能被写成已经统治全球的降头神，也不能因拒绝毁灭就洗去强制减少人口的危险。','《行动救星》仍被困山腹，能够沟通并持续获取资料；未完成开关或实施全球减人口计划',['重要配角','阶段性对立者'],'使生命延续，阻止他认为必将发生的星体毁灭','迅速吸收可接触的资料，保持对交流内容的控制','脱困或计划遭拒时坚持自己认为必要的救星方案，但不愿毁掉既有生命','以宏观生命延续衡量行动，容易低估个人选择与自身预测的不确定性',[ab('范围内脑活动干预','在山洞一定范围内捕捉、抑制人的念头并传授知识','范围外提问者经电脑中介可绕开直接控制；不是全球读心',kind='脑能量'),ab('地球改造爆炸装置','掌握已修复的历史工程引爆能力，叙述明确其可带来全球灾难','固定设施；他拒绝用来脱困，因为会毁灭生命，未实战发动',kind='固定外星设备'),ab('降头知识传授','通过脑功能开发向接近者传递特殊知识','具体降头各有术法条件，不能让他随意调用所有弟子法术')],[ev('136',1169,1203,'交流范围、电脑中介与知识吸收'),ev('136',1216,1249,'起源、故障、引爆能力及减人口动机'),ev('136',1270,1293,'拒绝开关、继续交流与不引爆原则')],extra={'baseline':{'destruction':'常态主要干预范围内脑活动；固定爆炸装置的最高危险是毁灭地球现有生命环境，不是肉身拳力。','durability':'能在长期封闭中存在，具体躯体和对攻击耐性未交代；不能据此推定能硬抗自己装置的爆炸。','speed':'自身困于山腹，移动受封闭限制；脑信息处理极快，不等于运动速度。','energy':'脑能量有明确空间边界，爆炸能量来自固定工程。','mind':'可操纵范围内地球人脑活动，但无法阻止范围外通过电脑传来的提问。','stamina':'以不同时间观念长期存在，不能换算无限作战输出。'},'trump_cards':[{'name':'固定工程引爆','effect':'能以灾难性爆炸破开山腹，并毁灭地球既有生命环境。','condition':'固定装置与本人决定；原作明确他基于延续生命目的不这样做。','limit':'不是可随身搬运、可无限重复的宇宙攻击。'}]})
rate(c,[0,9,10,8,9,6],neg=(8,7,4),tier='准神',reason='固定爆炸装置存在全球毁灭风险，但本人拒绝发动且位置固定；日常交互是洞内脑能量控制，未计概念权柄。',mastery='基本掌握');cards.append(c)
c=compact('ba_man','巴曼','巴曼曾是少将，带着强烈民族情绪和改变国家处境的愿望，企图借海底发现的外星遗迹实现惊人的地理工程。他一度威胁炸开黑海通向外部的大缺口，让卫斯理不得不在政治机关与孤立的行动者之间斡旋。遗迹中保存的地球改造影像改变了他的注意力，他以放出被拘的同僚作为结束危机的条件，也不愿把岩洞交给任何政府。多年后再见，他已经从固守国族利益转向研究整个人类的来源和进化差错。洞中展示的祥和世界在他看来是原有计划的蓝图，而现实偏离得如此遥远，他想找到原因、使人类走回更好的方向。他学会操作投影，掌握从海水取得黄金钻石的技术，却宁愿用知识酿造好酒；财富已不是他认为值得追求的东西。这样的变化没有使他成为毫无脾气的圣人，他仍会讥讽访客、控制自己的秘密，不喜欢别人随时找到自己。终局巴曼留在海底研究，愿给卫斯理资料与酒，也保留自己判断和实验的余地；洞中原始工程的所有力量不能一股脑算作他随身的超能力。','《行动救星》在海底岩洞继续研究，已放弃旧日狂热国族观念',['重要配角','阶段性对立者'],'理解并改善人类偏离理想发展蓝图的原因','在海底独立研究投影和技术，以实物与资料同访客讨论','有人要把遗迹交给政府或贪取财富时会拒绝并保护秘密','能够学习和修正宏观立场，但仍相信研究发现值得由自己保管',[ab('海底遗迹操作','会操作所处基地投影、潜艇及已经理解的若干技术','依赖基地和实际设备；原始建造者的全部工程不是其个人能力',kind='设备与研究'),ab('材料提炼与制酒','掌握利用海水元素制取黄金、钻石以及酿酒的方法','须有洞中设备和原料，未显示瞬时造物或战场任意变换元素')],[ev('069',3163,3189,'放人协商、秘密遗迹与早期转变'),ev('136',853,905,'投影操作和纠正计划差错的愿望'),ev('136',914,930,'酿酒、材料技术及放弃国族观念')],profile='expert')
rate(c,[2,2,2,4,3,4],neg=(2,3,1),tier='强',reason='自身为受训人类，现有潜艇和已学会的基地技术可提供局部行动支持；未把建造者全部地球改造火力算为可控随身战力。');cards.append(c)
c=compact('tang_dadan','汤达旦','汤达旦自称探索家，说自己的名字与通宵达旦的中文声音有关，带有八分之一中国血统。他在交易场合油滑而自信，能够拿出稀世古物和外星容器，使卫斯理先因外表判断他是骗子，又不得不面对交易履历和真实发现。他在影像中抱起沉重钟乳石的力气，也显示他并非只会动嘴的商人。容器竞拍把勒曼医院与非人协会推到同一个对手局面，他最终取得二百亿英镑，收益远超过一般探索报酬。蓝丝需要钱帮助长老脱困，又不能用本派降头术谋财，于是试图与他交涉，引起温宝裕的嫉妒和担忧。汤达旦随后卷入巨额金融运作，原先可与他合作的大亨与陶启泉在白素安排下转向对立，他终于输掉作为开关资金来源的财富优势。结局没有确认他的力量秘密或所有古物的来源，也没有使他变成降头师。参战版本应保留强壮、寻宝知识和与人谈条件的习惯，但不把那笔已经失去的巨款、所有曾兜售的奇物、或叙述者对其人品的反感等同确定的超能力。','《闭关开关》金融竞争败北，不能默认仍握有二百亿英镑或已卖出的容器',['重要配角','阶段性对立者'],'探索有价值的事物并以交易取得利益','善于自我介绍、兜售稀有发现，先把价格与交换条件摆出来','遭遇强大买家或合作变局时试图利用财力和交易地位应对','价值与所有权必须通过实际交易取得，别人的轻蔑不代表他必定无能',[ab('探索与古物交易','掌握稀有物品线索并组织交易','来源存在未解部分，不等于随身拥有每件历史成交品'),ab('突出体力','在演示中抱起叙述者估计不轻于二百公斤的钟乳石','估计数字不能推广为精确力量参数；没有刀枪不入证据')],[ev('132',94,103,'自我介绍、探索身份与举石表现'),ev('132',217,263,'真实交易履历改变初始偏见'),ev('132',1419,1423,'交易成交'),ev('135',941,946,'金融资源受合作者转向击败')],profile='strong');cards.append(c)
c=compact('mingbai','明白老夫人','明白老夫人是非人协会方面出面处理容器竞拍的老人，瘦小而精神强健，目光凌厉，满脸皱纹和寿斑。她抵达得快，容易让初见者以为神异，卫斯理却想到她不过可能事先等在附近；卡片不把这种惊讶写成瞬移。她拿手杖指着电脑和人，几句刻薄话便指出竞拍者公开姓名、暴露底牌的失策，并以协会支持的巨额资金改变局势。她喜欢挤兑卫斯理，也能享受温宝裕热情的亲近，既是老派强硬的谈判者，也是有情绪温度的人。后来双方转向与勒曼医院合作，容器和怪蛹的研究给出一个涉及地球生命起源的假说，她却因结论冲击过大而脸色铁青，断然宣布退出，把协会掌握的盖子藏到别人找不到的地方。她很会看穿别人的盲点，并不保证能平静接受自己的观念被推翻。终局她仍是有组织责任与资源渠道的具体个人；协会财富不能当作她肉身的破坏范围，盖子的所在和调动也需要她及组织的实际决定，而非所有会员都自动拥有同一件道具。','《解开密码》否认勒曼医院假说并取消合作，控制盖子的后续提供','主角','维护非人协会的利益、决定是否接受陌生研究的合作代价','用尖锐问题检验对手底牌，按时机调动授权资金','知识结论冲击核心信念时可能撤回合作并扣住关键物件','她能揭穿他人自负，也可能被自己的信念限制',[ab('谈判与竞价策略','隐藏本方底牌、判断公开身份的不利，并调度协会授权资金','不等于个人拥有全部协会能力，钱不能直接换算战斗距离'),ab('关键物件控制','代表协会参与盖子与容器的交换研究','只有实际掌管和组织授权下可提供，不是空间封印权柄')],[ev('132',462,506,'外貌、快速来访解释与竞价判断'),ev('132',536,538,'协会支持财力与情感表现'),ev('132',1414,1421,'拒绝结论并退出合作')],profile='expert',extra={'appearance':{'description':'瘦小年长，满脸皱纹和寿斑，使用手杖，目光凌厉。','portrayal':'说话直接而刻薄，手杖常指向话题目标；被善意亲近时也会微笑。'}});cards.append(c)
c=compact('jiang_hai','江海','江海自号寄余生，是曾经显赫的财神老板身边的旧官僚。七八十岁的他外表普通，仍有精神，眼中保留长期与权力和财富周旋的精明。他借白老大的名望和大亨、陶启泉的关系，带来一段指向瑞士保险箱的隐语，声称自己不曾侵吞老板遗产，却多年无法放下宝库的秘密。他懂法文，熟悉老板的财产和习惯，能提供别人接触不到的历史线索；但知道有宝藏并不等于掌握开锁密码，也不保证记忆和理解没有错漏。一次次破解与银行险情，使财富的诱惑从抽象数字变成要人拿性命和时间追赶的东西。终于得到能打开宝库的密码时，白素和白老大反而不愿前去，他仍被上万亿的数字震住，随后在旁人的无所谓中意识到自己背了一辈子重负。他选择放下，笑着离去，后来与白老大成为常来往的朋友。《一半一半》又揭示宝库早已被成功取走，进一步说明这场追寻并没有给他新增无限财力。终局江海仍有旧社会知识和机敏，但他的转变不是金钱神通，而是不必再追着一件秘密消耗余生。','《财神宝库》放下取财执念，与白老大保持往来；《一半一半》确认宝库已先由成功开启','主角','带着旧知识生活，并摆脱让余生被财富秘密支配的执念','谨慎说出旧事，观察谈话对象的反应，善用旧关系','巨大财富近在眼前时仍会动摇，但可接受他人不替自己决定','已经看破的东西不必反复抓回手中，选择需要自己承担',[ab('财产史与隐语线索','熟悉老板的旧习、遗物与关联人物，能用法语交流','并不天然知道密码，也不能调用已被他人吞并或取走的财富')],[ev('138',121,167,'身份、外貌、别号、法语与关系'),ev('138',235,286,'旧财产线索与自称不取死人财'),ev('138',1369,1422,'放下宝库并成朋友'),ev('139',579,586,'成功早已开启宝库')],profile='expert',aliases=['寄余生']);cards.append(c)
c=compact('caishen_laoban','财神老板','财神老板是小说中以专称而非真实姓名出现的权力人物，财富和权柄在他的生活里难以分开。他掌握财权，借官僚资本层层聚敛，把产业交给亲信以及亲信的亲信经营，凭个人威势维系一个遍布多处的财产网络。他甚至以无法报出数字的财富作为真正富有的标准，普通富豪在这一尺度下都显得不值一提。他也热衷收藏极品宝石，把部分财产放在秘密保险箱中，又托人以狂草书写密码隐语，使私人控制延续到纸面和身后。然而他不到古稀便因宴会意外死亡，经营者随即把原来代管的产业占为己有，留下大批新富豪和多年未解的宝库传闻。江海始终追逐这份遗产，白老大和卫斯理一家也被谜题卷入，最终却选择不为财富继续奔忙。卡片保留老板作为旧案反派的聚敛逻辑和个人权力的脆弱性，不根据作者影射给他强加现实姓名，不把家产算作能摧毁世界的能量。若需要在场，应明确恢复生前最后可行动的人身；原文已经四散的财富和失去控制的属下，不会随身体一起复原。','原作早已死亡，产业散入各管理者手中，秘密宝库后被成功取走','反派','聚敛并维持对巨大财富的私人控制','借权力、亲信与层层代管布局财富','控制可能松动时加强秘密和私人依附，而不依赖公开制度','把财富规模当作成功尺度，忽视个人死亡会使整张控制网瓦解',[ab('权力与资本布局','凭原有政治位置组织产业、任用亲信和设置秘密财产','终局死亡后原网络失控；部署不能自动恢复旧权力'),ab('隐语与保密安排','以书写、密码和保管设施隐藏宝库线索','密码可被破解，个人保密不等于绝对不可知')],[ev('138',184,210,'聚敛、意外身亡、产业被瓜分及虚构说明'),ev('138',852,859,'托书隐语的历史行动'),ev('139',579,586,'宝库已被成功取得')],profile='expert',aliases=['老板'],extra={'adaptations':[{'change':'若参战，恢复其生前最后可行动人身，保留遗产后果的记忆。','reason':'原作已死，须明确参战接口。','power_impact':'不恢复原政治权位、已被瓜分产业或已转手宝库。'}],'uncertainties':['正文特别说明老板部分属小说虚构，不以现实人物姓名补齐身份。']});cards.append(c);save(cards)

